import { MeshBasicNodeMaterial } from 'three/webgpu';
import { } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Plane geometry – size will be scaled by the parent/adapter if needed
  const geometry = new PlaneGeometry(1, 1, 1, 1);

  // Basic unlit material; texture will be applied once loaded
  const material = new MeshBasicNodeMaterial();

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load the image texture asynchronously; the function itself stays synchronous
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply any cinematic primitives listed in the config (none for this node)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name];
      if (handler) {
        const result = handler(root, prim.params);
        // Store for cleanup
        (root.userData._primitiveResults = root.userData._primitiveResults || []).push(result);
        // Attach to triggers (not required for this spec, but kept for completeness)
        if (prim.trigger) {
          // Primitive implementations handle their own triggers internally
        }
      }
    }
  }

  // No custom event handlers – ensure the property exists
  root.userData.handlers = {};

  // Cleanup routine: dispose resources and kill any GSAP timelines / primitives
  root.userData.cleanup = () => {
    // Stop any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();

    // Cleanup primitives
    if (root.userData._primitiveResults) {
      for (const res of root.userData._primitiveResults) {
        if (res && typeof res.cleanup === 'function') {
          res.cleanup();
        }
      }
    }

    // Dispose Three.js resources
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
  };

  return root;
}
